// ————— Placement: the first-visit wizard's answers and the review quizzes —————
// HAND-MAINTAINED. Not generated by build-vite-app.py (its data file,
// placementData.js, is).
//
// Lloyd, Oct 7–8 2026. A learner who has studied before says what they can
// already do, and for each section is offered a REVIEW QUIZ. The quiz does not
// start then — it waits at the top of that section. The shape, decided in
// conversation:
//
//   · ONE QUIZ PER LESSON GROUP inside the stage. Passing every group quiz
//     unlocks the STAGE quiz.
//   · PASSING THE STAGE QUIZ credits that stage's lessons as done (`placed`),
//     so the learner starts after them. A group pass credits nothing on its
//     own — it is the way to the stage quiz.
//   · THE PASS MARK IS ABOUT TWO-THIRDS — Lloyd: "around 65–70%". passMark()
//     below; quiz sizes are chosen so it lands there (10 → 7, 15 → 10).
//   · BELOW 60% the quiz locks for a week, and the result names the parts to
//     go back to. Between 60% and the pass mark it simply has not passed yet
//     and can be retried at once.
//   · Grammar is ASKED but has no quiz yet (its fill-in-the-blank quiz is a
//     separate session). The answer is recorded so the quiz can appear for
//     everyone who said yes when it ships.
//
// ⚠️ NO ROMAJI. Kana questions are spoken (the module's own audio sprite) and
// answered in kana; kanji questions give the English meaning and are answered
// in kanji. That is how the modules' own drills already avoid romaji.

import { storage } from "./storage.js";
import { HIRAGANA, KATAKANA, KANJI } from "./placementData.js";

export const PLACEMENT_KEY = "tsumiki-placement-v1";
export const LOCK_BELOW = 0.6;
export const LOCK_DAYS = 7;
const DAY = 86400e3;

/** Right answers needed to pass n questions: two-thirds, rounded up. */
export const passMark = (n) => Math.ceil((n * 2) / 3);

// ————— The quizzes, derived from the modules' own tables —————
function kanaItems(T, lessonIds) {
  const out = [];
  const add = (kana, sound) => { if (kana && sound && !out.some((x) => x.q === kana)) out.push({ q: kana, sound }); };
  for (const id of lessonIds) {
    const col = (T.COLS || []).find((c) => c.key === id);
    if (col) {
      col.kana.forEach((k, i) => add(k, col.sounds[i]));
      if (id === "wa") add(T === HIRAGANA ? "ん" : "ン", (T.EXTRA_SOUND || {})[T === HIRAGANA ? "ん" : "ン"] || "n");
    }
    if (id === "dakuten") {
      for (const k of [...Object.values(T.DAKUTEN || {}), ...Object.values(T.HANDAKU || {})]) add(k, (T.EXTRA_SOUND || {})[k]);
    }
  }
  return out;
}
const lessonsOf = (group) => group.ids.filter((id) => !id.startsWith("cc-"));

function kanaSection(id, name, T) {
  const groups = [];
  (T.GROUPS || []).forEach((g, i) => {
    const items = kanaItems(T, g.ids);
    // A group with nothing that can be SPOKEN (all culture, loanword or
    // judgment lessons) has no quiz, and is not credited by the stage quiz.
    if (items.length < 4) return;
    groups.push({ id: `${id}:g${i + 1}`, title: g.title, items, n: Math.min(10, items.length), lessons: lessonsOf(g) });
  });
  return finishSection(id, name, "kana", groups);
}

function kanjiSection() {
  const groups = (KANJI.GROUPS || []).slice(0, 2).map((g, i) => {
    const items = [];
    for (const lid of g.ids) for (const c of KANJI.CHARS[lid] || []) {
      if (KANJI.K[c] && !items.some((x) => x.q === c)) items.push({ q: c, meaning: KANJI.K[c].m });
    }
    return { id: `kanji:g${i + 1}`, title: g.title, items, n: Math.min(10, items.length), lessons: g.ids };
  });
  return finishSection("kanji", "Kanji", "kanji", groups);
}

function finishSection(id, name, kind, groups) {
  const items = [];
  for (const g of groups) for (const it of g.items) if (!items.some((x) => x.q === it.q)) items.push(it);
  const stage = {
    id: `${id}:stage`, title: kind === "kanji" ? "The first two groups, together" : `The whole chart`,
    items, n: Math.min(15, items.length), requires: groups.map((g) => g.id), lessons: groups.flatMap((g) => g.lessons),
  };
  return { id, name, kind, groups, stage, quizzes: [...groups, stage] };
}

export const SECTIONS = {
  hiragana: kanaSection("hiragana", "Hiragana", HIRAGANA),
  katakana: kanaSection("katakana", "Katakana", KATAKANA),
  kanji: kanjiSection(),
};
export const QUIZ = Object.fromEntries(Object.values(SECTIONS).flatMap((s) => s.quizzes.map((q) => [q.id, { ...q, section: s.id }])));

// Where each item lives, for "the parts to go back to".
function groupOfItem(sectionId, q) {
  return SECTIONS[sectionId].groups.find((g) => g.items.some((x) => x.q === q));
}

// ————— Questions —————
const shuffle = (a) => { const b = [...a]; for (let i = b.length - 1; i > 0; i--) { const j = Math.floor(Math.random() * (i + 1)); [b[i], b[j]] = [b[j], b[i]]; } return b; };
export function buildQuestions(quizId) {
  const quiz = QUIZ[quizId];
  const section = SECTIONS[quiz.section];
  const pool = section.stage.items;
  return shuffle(quiz.items).slice(0, quiz.n).map((it) => {
    let wrong;
    if (section.kind === "kanji") {
      const look = (KANJI.K[it.q]?.look || []).filter((c) => KANJI.K[c] && c !== it.q);
      const rest = shuffle(Object.keys(KANJI.K).filter((c) => c !== it.q && !look.includes(c)));
      wrong = [...look, ...rest].slice(0, 3);
    } else {
      // Kana distractors from the same quiz first — the confusions that matter
      // are inside the group being tested — then the rest of the chart.
      const near = shuffle(quiz.items.filter((x) => x.q !== it.q).map((x) => x.q));
      const far = shuffle(pool.filter((x) => x.q !== it.q && !near.includes(x.q)).map((x) => x.q));
      wrong = [...near, ...far].slice(0, 5);
    }
    return { item: it, options: shuffle([it.q, ...wrong]) };
  });
}

// ————— The store —————
const parse = (s) => { try { return JSON.parse(s); } catch { return null; } };
const isObj = (x) => x && typeof x === "object" && !Array.isArray(x);
export function shapePlacement(raw) {
  const v = isObj(raw) ? raw : {};
  return { v: 1, answers: isObj(v.answers) ? v.answers : null, quizzes: isObj(v.quizzes) ? v.quizzes : {} };
}
export async function readPlacement() {
  try { const r = await storage.get(PLACEMENT_KEY); return shapePlacement(r ? parse(r.value) : null); }
  catch { return shapePlacement(null); }
}
let queue = Promise.resolve();
function write(step) {
  const run = queue.then(async () => {
    const st = await readPlacement();
    const out = step(st) || {};
    if (out.write !== false) {
      try { await storage.set(PLACEMENT_KEY, JSON.stringify(st)); } catch (e) { console.error("placement save failed", e); }
    }
    return { ...out, state: st };
  });
  queue = run.catch(() => {});
  return run;
}

/**
 * The wizard's answers. `knows`: which sections the learner says they have
 * studied; `quiz`: which review quizzes they said yes to; `writing`: the
 * "all of the above, and I want to practise writing sentences" box.
 * Saying yes to a section unlocks its GROUP quizzes; the stage quiz follows.
 */
export function recordAnswers({ studied, knows = {}, quiz = {}, writing = false }, now = Date.now()) {
  return write((st) => {
    st.answers = { at: now, studied: !!studied, knows, quiz, writing: !!writing };
    for (const [sec, yes] of Object.entries(quiz)) {
      if (!yes || !SECTIONS[sec]) continue;
      for (const g of SECTIONS[sec].groups) st.quizzes[g.id] = st.quizzes[g.id] || { unlocked: now, attempts: [] };
    }
    return {};
  });
}

/** passed | locked | available | waiting (stage, groups not all passed) | null (not offered) */
export function quizStatus(st, quizId, now = Date.now()) {
  const q = QUIZ[quizId];
  if (!q) return { state: null };
  const rec = st.quizzes[quizId];
  if (q.requires) {
    const groupsOffered = q.requires.every((g) => st.quizzes[g]);
    if (!groupsOffered) return { state: null };
    if (!q.requires.every((g) => st.quizzes[g]?.passed)) return { state: "waiting" };
  } else if (!rec) return { state: null };
  if (rec?.passed) return { state: "passed", at: rec.passed };
  if (rec?.lockedUntil && rec.lockedUntil > now) return { state: "locked", until: rec.lockedUntil };
  return { state: "available" };
}

export function sectionOffered(st, sectionId) {
  return !!SECTIONS[sectionId] && SECTIONS[sectionId].groups.some((g) => st.quizzes[g.id]);
}

/**
 * Record one attempt. Returns { passed, locked, until, weak } where `weak`
 * groups the missed items by the lesson group they belong to — the parts to
 * go back to. A passed STAGE quiz credits the stage's lessons.
 */
export async function recordAttempt(quizId, { right, n, missed = [] }, now = Date.now()) {
  const q = QUIZ[quizId];
  const passed = right >= passMark(n);
  const locked = !passed && right / n < LOCK_BELOW;
  const res = await write((st) => {
    const rec = st.quizzes[quizId] || { unlocked: now, attempts: [] };
    rec.attempts = [...(rec.attempts || []), { ts: now, right, n }].slice(-20);
    if (passed && !rec.passed) rec.passed = now;
    if (locked) rec.lockedUntil = now + LOCK_DAYS * DAY;
    st.quizzes[quizId] = rec;
    return {};
  });
  const weakMap = new Map();
  for (const m of missed) {
    const g = groupOfItem(q.section, m);
    const key = g ? g.title : "";
    weakMap.set(key, [...(weakMap.get(key) || []), m]);
  }
  let credited = false;
  if (passed && q.requires) credited = await creditStage(q.section, now);
  return { passed, locked, until: locked ? now + LOCK_DAYS * DAY : null, weak: [...weakMap].map(([title, items]) => ({ title, items })), credited, state: res.state };
}

// ————— Crediting a stage —————
// Each module's done-test honours `placed` (one line in each module's isDone),
// so this writes an honest record — "placed out by the review quiz", with when
// — rather than faking drill scores the learner never produced.
const PROGRESS_KEY = {
  hiragana: "tsumiki-hiragana-progress-v2",
  katakana: "tsumiki-katakana-progress-v1",
  kanji: "tsumiki-kanji-progress-v1",
};
async function creditStage(sectionId, now) {
  const key = PROGRESS_KEY[sectionId];
  if (!key) return false;
  let prog = {};
  try { const r = await storage.get(key); prog = (r && parse(r.value)) || {}; } catch { prog = {}; }
  if (!isObj(prog)) prog = {};
  for (const id of SECTIONS[sectionId].stage.lessons) prog[id] = { ...(isObj(prog[id]) ? prog[id] : {}), placed: prog[id]?.placed || now };
  await storage.set(key, JSON.stringify(prog));
  if (sectionId === "kanji") {
    // Kanji the learner placed out of are kanji they can read: grammar and
    // vocabulary read this list to decide what to show in kanji.
    let known = [];
    try { const r = await storage.get("tsumiki-known-kanji-v1"); known = (r && parse(r.value)) || []; } catch { known = []; }
    if (!Array.isArray(known)) known = [];
    for (const it of SECTIONS.kanji.stage.items) if (!known.includes(it.q)) known.push(it.q);
    await storage.set("tsumiki-known-kanji-v1", JSON.stringify(known));
  }
  return true;
}
